// Renders the hand-drawn icon (scripts/draw-icon.py) with Blender, headless,
// into every size the app needs: the interface's logos, the large artwork,
// and the desktop icons (generated by `tauri icon` from the 1024 px render,
// with the bolder small-size drawing put into icon.ico and 32x32.png).
//
// Usage: pnpm icons
// Set BLENDER to the blender executable if it is not found automatically.
import { execFileSync } from 'node:child_process';
import {
  copyFileSync,
  existsSync,
  mkdirSync,
  readFileSync,
  readdirSync,
  writeFileSync,
} from 'node:fs';
import { join, resolve } from 'node:path';

function findBlender() {
  if (process.env.BLENDER) return process.env.BLENDER;
  const candidates = [];
  if (process.platform === 'win32') {
    const root = 'C:/Program Files/Blender Foundation';
    if (existsSync(root)) {
      for (const dir of readdirSync(root).sort().reverse())
        candidates.push(join(root, dir, 'blender.exe'));
    }
  } else if (process.platform === 'darwin') {
    candidates.push('/Applications/Blender.app/Contents/MacOS/Blender');
  }
  candidates.push('blender');
  return candidates.find((c) => c === 'blender' || existsSync(c));
}

const blender = findBlender();
const script = resolve('scripts/draw-icon.py');
const targets = [
  ...[16, 32, 48, 96, 128].map((size) => [size, resolve(`public/icon/${size}.png`)]),
  [512, resolve('assets/icon-512.png')],
  [1024, resolve('assets/icon-1024.png')],
  ...[16, 24, 256].map((size) => [size, resolve(`assets/ico/${size}.png`)]),
];
mkdirSync(resolve('assets/ico'), { recursive: true });
mkdirSync(resolve('public/icon'), { recursive: true });

for (const [size, out] of targets) {
  // --python-exit-code makes Blender fail when the script raises.
  execFileSync(
    blender,
    [
      '-b',
      '--factory-startup',
      '--python-exit-code',
      '1',
      '--python',
      script,
      '--',
      out,
      String(size),
    ],
    {
      stdio: ['ignore', 'ignore', 'inherit'],
    },
  );
  console.log(`${size}px  ${out}`);
}

// Desktop icons for every platform, then the bold small sizes for Windows.
execFileSync('pnpm', ['tauri', 'icon', 'assets/icon-1024.png', '-o', 'src-tauri/icons'], {
  stdio: 'inherit',
  shell: true,
});
for (const dir of ['android', 'ios']) {
  const path = resolve('src-tauri/icons', dir);
  if (existsSync(path))
    execFileSync(
      process.platform === 'win32' ? 'cmd' : 'rm',
      process.platform === 'win32' ? ['/c', 'rmdir', '/s', '/q', path] : ['-rf', path],
    );
}
copyFileSync(resolve('public/icon/32.png'), resolve('src-tauri/icons/32x32.png'));

/** An .ico holding PNG images (Windows Vista and later read these). */
function writeIco(out, sources) {
  const images = sources.map(([size, file]) => [size, readFileSync(file)]);
  const header = Buffer.alloc(6 + 16 * images.length);
  header.writeUInt16LE(0, 0);
  header.writeUInt16LE(1, 2);
  header.writeUInt16LE(images.length, 4);
  let offset = header.length;
  images.forEach(([size, data], i) => {
    const at = 6 + 16 * i;
    header.writeUInt8(size % 256, at);
    header.writeUInt8(size % 256, at + 1);
    header.writeUInt16LE(1, at + 4);
    header.writeUInt16LE(32, at + 6);
    header.writeUInt32LE(data.length, at + 8);
    header.writeUInt32LE(offset, at + 12);
    offset += data.length;
  });
  writeFileSync(out, Buffer.concat([header, ...images.map(([, data]) => data)]));
}

writeIco(resolve('src-tauri/icons/icon.ico'), [
  [16, resolve('assets/ico/16.png')],
  [24, resolve('assets/ico/24.png')],
  [32, resolve('public/icon/32.png')],
  [48, resolve('public/icon/48.png')],
  [256, resolve('assets/ico/256.png')],
]);
console.log('src-tauri/icons updated');
